use std::collections::HashMap;

fn two_sum(nums: &Vec<i32>, target: i32) -> Vec<usize> {
    // Map from number value to its index in `nums`
    let mut seen: HashMap<i32, usize> = HashMap::new();

    for (i, &num) in nums.iter().enumerate() {
        let complement = target - num;
        if let Some(&j) = seen.get(&complement) {
            // We found a previous index `j` such that nums[j] + nums[i] == target.
            // By construction j < i, so we can return [j, i].
            return vec![j, i];
        }
        // Record that we've now seen `num` at index `i`
        seen.insert(num, i);
    }

    // The problem guarantees exactly one solution, so we should never reach here.
    unreachable!("No two sum solution found");
}

